"""
Analyze aggregated end-to-end test failures and format a Slack report.

Failures extracted per browser and per run (see ``extract_e2e_test_results.py``)
are aggregated into ``failures_by_test`` before this module identifies flaky
candidates and renders a Slack Block Kit message.
"""

from __future__ import annotations

# The UI e2e suite runs on three browsers (see ``playwright.config.ts``), so the
# effective number of test executions is ``runs * BROWSER_COUNT``.
BROWSER_COUNT = 3

# A test must fail on more than this fraction of its executions to be flagged as
# a candidate. This keeps genuinely rare, one-off failures out of the report
# (e.g. 1 failure across 10 runs on 3 browsers -> 1/30 -> excluded).
MIN_FAILURE_RATE = 0.05

# Slack channel that receives the report.
SLACK_CHANNEL = "airflow-3-ui"


def escape_slack_mrkdwn(text: str) -> str:
    """Escape special characters for Slack ``mrkdwn`` formatting."""
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _failure_count(info: object) -> int:
    """Best-effort extraction of a failure count from an aggregated entry."""
    if isinstance(info, bool):
        return int(info)
    if isinstance(info, int):
        return info
    if isinstance(info, list):
        return len(info)
    if isinstance(info, dict):
        for key in ("count", "failure_count", "failures"):
            value = info.get(key)
            if isinstance(value, int):
                return value
            if isinstance(value, list):
                return len(value)
        for key in ("runs", "occurrences", "browsers"):
            value = info.get(key)
            if isinstance(value, list):
                return len(value)
    return 0


def _error_sample(info: object) -> str:
    """Best-effort extraction of a representative error message."""
    if isinstance(info, dict):
        errors = info.get("errors")
        if isinstance(errors, list) and errors:
            first = errors[0]
            if isinstance(first, dict):
                return str(first.get("error") or first.get("message") or "")
            return str(first)
        return str(info.get("error") or info.get("message") or "")
    return ""


def identify_flaky_candidates(failures_by_test: dict, runs_with_data: int) -> list:
    """Identify tests that exceed the minimum failure-rate threshold.

    Returns an empty list when there is no data. Each candidate dict contains at
    least ``test`` and ``failure_rate`` and the list is sorted by
    ``failure_rate`` descending.
    """
    if not failures_by_test or not runs_with_data:
        return []

    total_runs = runs_with_data * BROWSER_COUNT
    candidates: list = []
    for test, info in failures_by_test.items():
        count = _failure_count(info)
        if count <= 0:
            continue
        failure_rate = count / total_runs
        if failure_rate < MIN_FAILURE_RATE:
            continue
        candidates.append(
            {
                "test": test,
                "failure_count": count,
                "failure_rate": failure_rate,
                "error": _error_sample(info),
            }
        )

    candidates.sort(key=lambda candidate: candidate["failure_rate"], reverse=True)
    return candidates


def _section(text: str) -> dict:
    """Build a Slack ``section`` block with mrkdwn text."""
    return {"type": "section", "text": {"type": "mrkdwn", "text": text}}


def _fixme_names(fixme_tests: dict) -> list:
    """Normalize the fixme tests container into a list of test names."""
    if isinstance(fixme_tests, dict):
        return [str(name) for name in fixme_tests.keys()]
    if isinstance(fixme_tests, list):
        names = []
        for item in fixme_tests:
            if isinstance(item, dict):
                names.append(str(item.get("test", "")))
            else:
                names.append(str(item))
        return names
    return []


def format_slack_message(
    failures_by_test: dict,
    fixme_tests: dict,
    flaky_candidates: list,
    runs: list,
    runs_with_data: int,
    repo: str,
) -> dict:
    """Format the aggregated analysis as a Slack Block Kit message dict."""
    blocks: list = [
        {
            "type": "header",
            "text": {"type": "plain_text", "text": "E2E Flaky Test Report"},
        },
        _section(
            f"*Repository:* `{escape_slack_mrkdwn(repo)}`\n"
            f"*Runs analyzed:* {len(runs)} ({runs_with_data} with data)"
        ),
    ]

    # Failures section.
    if failures_by_test:
        blocks.append(_section("*Test failures:*"))
        for test, info in failures_by_test.items():
            count = _failure_count(info)
            error = escape_slack_mrkdwn(_error_sample(info))
            line = f"• `{escape_slack_mrkdwn(str(test))}` — {count} failure(s)"
            if error:
                line += f": {error}"
            blocks.append(_section(line))
    else:
        blocks.append(_section("✅ No test failures detected."))

    # Flaky candidates section.
    if flaky_candidates:
        blocks.append(_section("*Flaky test candidates:*"))
        for candidate in flaky_candidates:
            test = escape_slack_mrkdwn(str(candidate.get("test", "")))
            failure_rate = candidate.get("failure_rate", 0) or 0
            blocks.append(_section(f"• `{test}` — {failure_rate * 100:.1f}% failure rate"))
    else:
        blocks.append(_section("No flaky test candidates identified."))

    # Fixme section.
    fixme_names = _fixme_names(fixme_tests)
    if fixme_names:
        blocks.append(_section("*Tests marked with `fixme`:*"))
        for name in fixme_names:
            blocks.append(_section(f"• `{escape_slack_mrkdwn(name)}`"))

    return {
        "channel": SLACK_CHANNEL,
        "text": f"E2E Flaky Test Report for {repo}",
        "blocks": blocks,
    }
